import{_ as a,c as t,o as i,al as n,aG as s,aH as r,aI as l,aJ as m,aK as u}from"./chunks/framework.BUk2DuAG.js";const f=JSON.parse('{"title":"Estim Modul","description":"","frontmatter":{},"headers":[],"relativePath":"de/modules/estim.md","filePath":"de/modules/estim.md"}'),d={name:"de/modules/estim.md"};function o(h,e,c,p,g,_){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="estim-modul" tabindex="-1">Estim Modul <a class="header-anchor" href="#estim-modul" aria-label="Permalink to “Estim Modul”">​</a></h1><p>Grundsätzlich besteht das Estim Modul aus einer umgebauten und modifizierten 2B Power Box von E-STIM Systems. Die Batterieunterstützung ist komplett raus geflogen. Dazu habe ich den Spannungsregler ersetzt, damit ich mit der 12V Versorgung besser arbeiten kann. Die Intensität lässt sich ansonsten weniger gut Regeln.</p><p>Die Bedienung habe ich nahezu wie beim 2B gelassen. Das heißt das Estim Modul kann auch wie ein 2B arbeiten ohne eine Rückläufige Anbindung. Das ist ganz praktisch weil ich damit auch Tests mit neuen Elektroden machen kann.</p><p>Die Verbindungen mit der Steuerplatine habe ich absichtlich nach außen geführt. So kann ich die Software Commander von E-STIM Systems zusätzlich verwenden. Wobei ich die Funktionalität mittlerweile an meine Belange angepasst habe und ein eigenes Software-Interface dazu erstellt habe.</p><h2 id="aufbau" tabindex="-1">Aufbau <a class="header-anchor" href="#aufbau" aria-label="Permalink to “Aufbau”">​</a></h2><p><a href="/images/modules/estim/estim_modul_structure.png" target="_blank"><img src="'+s+'" alt="Estim Modul Structure"></a></p><h2 id="multiplexer" tabindex="-1">Multiplexer <a class="header-anchor" href="#multiplexer" aria-label="Permalink to “Multiplexer”">​</a></h2><p>Zu den Steuerungsfunktionalitäten des Moduls, habe ich mich dafür entschieden, einen Multiplexer zu integrieren. Damit kann ich aus den beiden Kanälen A und B, vier Ausgänge machen. Natürlich lassen sich die vier Ausgänge nicht simultan betreiben. Trotzdem lassen sich vier Elektroden an zwei Kanälen umschalten.</p><h2 id="gehause" tabindex="-1">Gehäuse <a class="header-anchor" href="#gehause" aria-label="Permalink to “Gehäuse”">​</a></h2><p><a href="/images/modules/estim/estim_case_frontpanel.png" target="_blank"><img src="'+r+'" alt="Estim Case Frontpanel"></a></p><p><a href="/images/modules/estim/estim_case_backpanel.png" target="_blank"><img src="'+l+'" alt="Estim Case Backpanel"></a></p><p><a href="/images/modules/estim/estim_case_multiplexer_frontpanel.png" target="_blank"><img src="'+m+'" alt="Estim Case Multiplexer Frontpanel"></a></p><p><a href="/images/modules/estim/estim_case_multiplexer_backpanel.png" target="_blank"><img src="'+u+'" alt="Estim Case Multiplexer Backpanel"></a></p>',13)])])}const k=a(d,[["render",o]]);export{f as __pageData,k as default};
